Audio Synthesis and Processing:
// FAUST to Wasm audio workflow
// 1. Write DSP in FAUST
//    process = *0.5 : + ~ _;
// 2. Compile: faust2wasm synth.dsp
// 3. Use in AudioWorklet

class SynthWorklet extends AudioWorkletProcessor {
  constructor() {
    super();
    this.wasmReady = WebAssembly
      .instantiateStreaming(fetch('synth.wasm'))
      .then(({ instance }) => { this.module = instance.exports; });
  }
  process(inputs, outputs) {
    const output = outputs[0];
    for (let ch = 0; ch < output.length; ch++) {
      const channel = output[ch];
      for (let i = 0; i < channel.length; i++) {
        channel[i] = this.module.process();
      }
    }
    return true;
  }
}
registerProcessor('synth', SynthWorklet);

