Blockchain and Smart Contracts:
// Polkadot/Substrate ink! smart contract (Rust → Wasm)
#[ink::contract]
pub mod erc20 {
    #[ink(storage)]
    pub struct Erc20 {
        total_supply: Balance,
        balances: ink_storage::Mapping<AccountId, Balance>,
    }

    impl Erc20 {
        #[ink(constructor)]
        pub fn new(total_supply: Balance) -> Self {
            let mut balances = ink_storage::Mapping::default();
            let caller = Self::env().caller();
            balances.insert(caller, &total_supply);
            Self { total_supply, balances }
        }

        #[ink(message)]
        pub fn transfer(&mut self, to: AccountId, value: Balance) -> bool {
            let from = self.env().caller();
            let balance = self.balances.get(&from).unwrap_or(0);
            if balance < value { return false; }
            self.balances.insert(&from, &(balance - value));
            let to_balance = self.balances.get(&to).unwrap_or(0);
            self.balances.insert(&to, &(to_balance + value));
            true
        }
    }
}

// Build: cargo contract build
// Output: target/ink/erc20.wasm

