// WASI file I/O in Rust
use std::fs;
use std::io::Read;

fn main() {
    // Read a file (WASI provides file system access)
    let mut file = fs::File::open("/data/input.txt").unwrap();
    let mut contents = String::new();
    file.read_to_string(&mut contents).unwrap();

    // Process data
    let processed = contents.to_uppercase();

    // Write output
    fs::write("/data/output.txt", processed).unwrap();

    println!("File processed successfully!");
}

